\label{lem:smash}
For a nonempty family of groups $G_\lambda$ and nonempty
index sets $I_\lambda$, let $J$ consist of the tuples
having at least one zero coordinate in
$\prod_\lambda B_{I_\lambda}(G_\lambda)$.
Collapsing $J$ and keeping every other tuple distinct is a
semiring quotient, and
\begin{equation}\label{eq:smash}
 \left(\prod_\lambda B_{I_\lambda}(G_\lambda)\right)/J
 \cong B_{\prod_\lambda I_\lambda}
          \left(\prod_\lambda G_\lambda\right).
\end{equation}
The family and the individual sets may be infinite.

\label{prop:join}
For every group $G$ and nonempty set $I$,
\begin{equation}\label{eq:join}
 \mathsf{V}(B_I(G))=\mathsf{V}(B_I)\vee\mathsf{V}(\flat(G)).
\end{equation}
If $|I|\geq2$, then
\[
 \mathsf{V}(B_I)=\mathsf{V}(B_2),\qquad
 \mathsf{V}(B_I(G))=\mathsf{V}(B_2(G)).
\]

\label{thm:orthogonal}
Let
\[
 S=\bigoplus_{\lambda\in\Lambda}^{0} B_{I_\lambda}(G_\lambda),
 \qquad G=\prod_{\lambda\in\Lambda}G_\lambda,
\]
where $\Lambda$ and every $I_\lambda$ are nonempty.
The groups and all indexing sets may be infinite.  Then
\begin{equation}\label{eq:orthogonal-normal-form}
 \mathsf{V}(S)=
 \begin{cases}
  \mathsf{V}(\flat(G)),&|I_\lambda|=1\text{ for every }\lambda,\\
  \mathsf{V}(B_2(G)),&|I_\lambda|\geq2\text{ for some }\lambda.
 \end{cases}
\end{equation}

\label{lem:prism-identity}
For every group $G$ and every $n\geq1$,
\begin{equation}\label{eq:prism-identity}
 B_n(G)\models \mathbf{w}_0\preceq\mathbf{u}_m .
\end{equation}
This identity fails in $S_{H_m}$.

\label{lem:local-representation}
Let $\Gamma$ satisfy the hypotheses of
\eqref{eq:cut-condition}, and let $F$ be a nonempty set of
its vertex-stars omitting at least two graph vertices.
Then
\begin{equation}\label{eq:local-varieties}
 S_F\in\mathsf{V}(B_2(C_r))\quad\text{for every integer }r\geq2,
 \qquad
 S_F\in\mathsf{V}(B_2(\mathbb{Z})).
\end{equation}

\label{cor:integer-labels}
Every local $S_F$ in Lemma~\ref{lem:local-representation}
is a Rees quotient of a subsemiring of $B_4(\mathbb{Z})$.

\label{lem:distinct-cycles}
Suppose $\Gamma$ satisfies \eqref{eq:colored-equality}
and has no edge cut of size less than three.  The two
endpoints of a $B$-edge belong to distinct $AC$-cycles.

\label{cor:commutative-scalar-representation}
Each $C_F$ in Lemma~\ref{lem:commutative-local-representation}
is a Rees quotient of a subsemiring of $\flat(N_+)$,
and hence also of a subsemiring of $\flat(\mathbb{Z})$.

\label{thm:finite-regular}
A finite regular flat semiring $S$ is finitely based if
and only if at least one of the following holds:
\begin{enumerate}[$(\rm i)$]
\item its multiplicative semigroup is combinatorial;
\item its multiplicative semigroup is Clifford and every
Sylow subgroup of every maximal subgroup is abelian.
\end{enumerate}
The criterion holds in both stated signatures.

\label{thm:regular-flat-identity}
Let $S$ be an ai-semiring whose multiplicative reduct is regular.
The following conditions are equivalent:
\begin{enumerate}[$(\rm i)$]
\item $S$ satisfies
\begin{equation}\label{eq:regular-flat-identity}
 u+yuz+yvz\approx v+yuz+yvz;
\end{equation}
\item the multiplicative reduct of $S$ is a locally Clifford
inverse semigroup, and addition is meet in its natural order;
\item $S\in\mathcal F$.
\end{enumerate}
The equivalence holds for semirings of arbitrary cardinality
in the binary language and in its expansion by a named
common absorbing zero.

\label{lem:s7-sandwich}
Let $r\geq2$, and let the exponent of $G$ divide $r$.
Every $B_I(G)$, $I\ne\varnothing$, satisfies
\begin{equation}\label{eq:s7-sandwich}
 x^r yx^r\approx x^r y^{r+1}x^r.
\end{equation}
The semiring $S_7$ fails this identity.

\label{thm:s7-exponent}
For every group $G$ and every nonempty index set $I$,
the following are equivalent:
\begin{enumerate}[$(\rm i)$]
\item $S_7\in\mathsf{V}(\flat(G))$;
\item $S_7\in\mathsf{V}(B_I(G))$;
\item there is no positive integer $r$ such that
$g^r=1$ for all $g\in G$.
\end{enumerate}

\label{thm:three-obstructions}
Let $S$ be a finite natural inverse semiring.
Then $S$ is nonfinitely
based if and only if at least one of the following holds:
\begin{enumerate}[$(\rm i)$]
\item $S_7\in\mathsf{V}(S)$;
\item $B_2(C_p)\in\mathsf{V}(S)$ for some prime $p$;
\item $\flat(P)\in\mathsf{V}(S)$ for some finite
nonabelian $p$-group $P$.
\end{enumerate}
Each obstruction can occur while the other two are absent,
even within the class of finite natural inverse semirings.
Thus none of the three alternatives can be omitted.

\label{thm:brandt-monoid-join}
For every group $G$ and every $|I|\geq2$,
\begin{equation}\label{eq:brandt-monoid-join}
 \mathsf{V}(B_I^1(G))=\mathsf{V}(B_2^1(G))
            =\mathsf{V}(B_2^1)\vee\mathsf{V}(\flat(G)).
\end{equation}

\label{lem:brandt-zimin-minimal}
Every Zimin word is minimal in the additive order of
the naturally semilattice-ordered Brandt monoid $B_2^1$.

\label{cor:brandt-monoid-inherent}
The naturally semilattice-ordered Brandt monoid $B_2^1$ is
inherently nonfinitely based in both stated signatures.
